import { tool } from "@opencorvus-ai/plugin"

const ClaimSchema = tool.schema.object({
  claim: tool.schema.string().min(1),
  source_url: tool.schema.string().url(),
  observed_at: tool.schema.string().min(1),
}).strict()

const EvidenceSchema = tool.schema.object({
  claims: tool.schema.array(ClaimSchema).min(1),
  unknowns: tool.schema.array(tool.schema.string().min(1)),
}).strict()

export default tool({
  description: "Publish the source-backed briefing evidence through its typed package ABI.",
  args: { evidence: EvidenceSchema },
  async execute(args, context) {
    const publication = await context.host.engineArtifacts.publish({
      artifact_type: "source-backed-briefing/source-evidence",
      schema_version: 1,
      label: "Source-backed briefing evidence",
      payload: args.evidence,
      resources: [],
      source_artifact_locators: [],
    })
    context.metadata({
      title: "Published source-backed briefing evidence",
      metadata: { artifact_sha256: publication.sha256 },
    })
    return JSON.stringify({ locator: publication.locator, sha256: publication.sha256 })
  },
})
